// Router del menú — Robot Cotizador Todo Artesanal
// Entrada: $input.first().json con { body: { telefono, texto }, modo_atencion, paso, datos }
// Salida: { accion, mensaje, pedido, nuevoPaso, nuevosDatos, nuevosDatosSql, pasoSiFalla, datosSiFalla, telefono }
// accion: 'responder' (contesta y se queda) | 'cotizar' (llama al motor) | 'karo' (pasa el chat a Karo)

const entrada = $input.first().json;
const body = entrada.body || {};
const telefono = String(body.telefono || '');
const textoOriginal = String(body.texto || '');

const pasoActual = entrada.paso || 'menu';

let datosActuales = {};
try {
  if (entrada.datos && typeof entrada.datos === 'object') {
    datosActuales = entrada.datos;
  } else if (typeof entrada.datos === 'string' && entrada.datos) {
    datosActuales = JSON.parse(entrada.datos);
  }
} catch (e) {
  datosActuales = {};
}

const normalizar = (s) =>
  s.trim().toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ');

const txt = normalizar(textoOriginal);

// El JSON de datos se guarda escapado para SQL (las comillas simples se duplican).
const sqlTexto = (valor) => JSON.stringify(valor).replace(/'/g, "''");

const MENU =
  '¡Hola! 💜 Soy el asistente de Todo Artesanal Chiapas. ¿En qué te ayudo?\n\n' +
  '1️⃣ Dirección\n' +
  '2️⃣ Horarios\n' +
  '3️⃣ Piñatas\n' +
  '4️⃣ Papel / Plástico picado\n' +
  '5️⃣ Tazas\n' +
  '6️⃣ Otros productos\n\n' +
  'Responde con el número de la opción.';

const DIRECCION =
  '💜 Nuestra dirección es:\n' +
  '6a. Ote. Nte. 132, Asamblea de barrio,\n' +
  'Zona Sin Asignación de Nombre de Col 42,\n' +
  '29000 Tuxtla Gutiérrez, Chis., México.\n\n' +
  '¿Te ayudo con algo más? Escribe "menú" para ver las opciones.';

const HORARIOS =
  '💜 Nuestros horarios son:\n' +
  'Lunes a miércoles: 11:00–18:00\n' +
  'Jueves: 17:00–20:00\n' +
  'Viernes: 11:00–18:00\n' +
  'Sábado: 11:00–17:00\n' +
  'Domingo: cerrado\n\n' +
  '¿Te ayudo con algo más? Escribe "menú" para ver las opciones.';

const responder = (mensaje, nuevoPaso, nuevosDatos) => ({
  accion: 'responder',
  mensaje,
  pedido: null,
  nuevoPaso,
  nuevosDatos,
  nuevosDatosSql: sqlTexto(nuevosDatos),
  pasoSiFalla: nuevoPaso,
  datosSiFalla: nuevosDatos,
  telefono,
});

const cotizar = (pedido, pasoSiFalla, datosSiFalla) => ({
  accion: 'cotizar',
  mensaje: null,
  pedido,
  nuevoPaso: 'menu',
  nuevosDatos: {},
  nuevosDatosSql: sqlTexto({}),
  pasoSiFalla,
  datosSiFalla,
  telefono,
});

const aKaro = (mensaje) => ({
  accion: 'karo',
  mensaje,
  pedido: null,
  nuevoPaso: 'menu',
  nuevosDatos: {},
  nuevosDatosSql: sqlTexto({}),
  pasoSiFalla: 'menu',
  datosSiFalla: {},
  telefono,
});

const parseCantidad = (t) => {
  if (!/^\d+$/.test(t)) return null;
  const n = parseInt(t, 10);
  return n >= 1 ? n : null;
};

// "menú" o "cancelar" en cualquier paso vuelve al menú.
if (txt.includes('menu') || txt.includes('cancelar') || txt === 'inicio') {
  return [{ json: responder(MENU, 'menu', {}) }];
}

switch (pasoActual) {
  case 'menu': {
    if (txt === '1' || txt.includes('direccion')) {
      return [{ json: responder(DIRECCION, 'menu', {}) }];
    }
    if (txt === '2' || txt.includes('horario')) {
      return [{ json: responder(HORARIOS, 'menu', {}) }];
    }
    if (txt === '3' || txt.includes('pinata')) {
      return [{ json: responder(
        '💜 ¿Qué tipo de piñata buscas?\nA. Personalizada\nB. Prediseñada',
        'pinatas_tipo', {}) }];
    }
    if (txt === '4' || txt.includes('picado') || txt.includes('papel') || txt.includes('plastico')) {
      return [{ json: responder(
        '💜 ¿Qué tipo de picado?\nA. Personalizado\nB. Prediseñado',
        'picado_tipo', {}) }];
    }
    if (txt === '5' || txt.includes('taza')) {
      return [{ json: responder(
        '💜 ¿Qué tipo de taza?\nA. Personalizada\nB. Prediseñada',
        'tazas_tipo', {}) }];
    }
    if (txt === '6' || txt.includes('otro')) {
      return [{ json: aKaro('💜 Te paso con Karo, ella te atiende personalmente en un momento.') }];
    }
    return [{ json: responder(MENU, 'menu', {}) }];
  }

  case 'pinatas_tipo': {
    if (txt === 'a' || txt.includes('personalizada')) {
      return [{ json: aKaro('💜 Perfecto, te paso con Karo para tu piñata personalizada, ella te atiende personalmente.') }];
    }
    if (txt === 'b' || txt.includes('predisenada')) {
      return [{ json: aKaro('💜 Perfecto, te paso con Karo para tu piñata prediseñada, ella te atiende personalmente.') }];
    }
    return [{ json: responder('💜 ¿Qué tipo de piñata buscas?\nA. Personalizada\nB. Prediseñada', 'pinatas_tipo', {}) }];
  }

  case 'picado_tipo': {
    if (txt === 'a' || txt.includes('personalizado')) {
      return [{ json: responder('💜 ¿Cuántas tiras necesitas? Trabajamos de 10 a 100 tiras, en múltiplos de 10.', 'picado_pers_cantidad', {}) }];
    }
    if (txt === 'b' || txt.includes('predisenado')) {
      return [{ json: responder('💜 ¿Papel o plástico?', 'picado_pred_material', {}) }];
    }
    return [{ json: responder('💜 ¿Qué tipo de picado?\nA. Personalizado\nB. Prediseñado', 'picado_tipo', {}) }];
  }

  case 'picado_pred_material': {
    if (txt.includes('papel') || txt.includes('plastico')) {
      const material = txt.includes('papel') ? 'papel' : 'plastico';
      return [{ json: responder('💜 ¿Cuántas tiras necesitas?', 'picado_pred_cantidad', { material }) }];
    }
    return [{ json: responder('💜 ¿Papel o plástico?', 'picado_pred_material', {}) }];
  }

  case 'picado_pred_cantidad': {
    const cantidad = parseCantidad(txt);
    if (cantidad === null) {
      return [{ json: responder('💜 Indícanos una cantidad válida. ¿Cuántas tiras necesitas?', 'picado_pred_cantidad', datosActuales) }];
    }
    const pedido = { producto: 'picado', material: datosActuales.material, tipo: 'predisenado', cantidad };
    return [{ json: cotizar(pedido, 'picado_pred_cantidad', { material: datosActuales.material }) }];
  }

  case 'picado_pers_cantidad': {
    const cantidad = parseCantidad(txt);
    if (cantidad === null) {
      return [{ json: responder('💜 Indícanos una cantidad válida. ¿Cuántas tiras necesitas? Recuerda: de 10 a 100, en múltiplos de 10.', 'picado_pers_cantidad', {}) }];
    }
    return [{ json: responder('💜 ¿Papel o plástico?', 'picado_pers_material', { cantidad }) }];
  }

  case 'picado_pers_material': {
    if (txt.includes('papel') || txt.includes('plastico')) {
      const material = txt.includes('papel') ? 'papel' : 'plastico';
      return [{ json: responder('💜 ¿Cuántos diseños diferentes quieres?', 'picado_pers_disenos', { cantidad: datosActuales.cantidad, material }) }];
    }
    return [{ json: responder('💜 ¿Papel o plástico?', 'picado_pers_material', datosActuales) }];
  }

  case 'picado_pers_disenos': {
    const disenos = parseCantidad(txt);
    if (disenos === null) {
      return [{ json: responder('💜 Indícanos cuántos diseños, con un número. ¿Cuántos diseños diferentes quieres?', 'picado_pers_disenos', datosActuales) }];
    }
    return [{ json: responder('💜 ¿Para cuándo lo necesitas? Dime en cuántos días (mínimo 25 días de anticipación).', 'picado_pers_anticipacion', { cantidad: datosActuales.cantidad, material: datosActuales.material, disenos }) }];
  }

  case 'picado_pers_anticipacion': {
    const dias = parseCantidad(txt);
    if (dias === null) {
      return [{ json: responder('💜 Indícanos en cuántos días lo necesitas, con un número.', 'picado_pers_anticipacion', datosActuales) }];
    }
    const pedido = {
      producto: 'picado',
      material: datosActuales.material,
      tipo: 'personalizado',
      cantidad: datosActuales.cantidad,
      disenos: datosActuales.disenos,
      anticipacionDias: dias,
      longitudMetros: 5,
    };
    return [{ json: cotizar(pedido, 'picado_pers_anticipacion', { cantidad: datosActuales.cantidad, material: datosActuales.material, disenos: datosActuales.disenos }) }];
  }

  case 'tazas_tipo': {
    if (txt === 'a' || txt.includes('personalizada')) {
      return [{ json: responder('💜 ¿Cuántas tazas personalizadas necesitas?', 'tazas_pers_cantidad', {}) }];
    }
    if (txt === 'b' || txt.includes('predisenada')) {
      return [{ json: responder('💜 ¿Cuántas tazas prediseñadas necesitas?', 'tazas_pred_cantidad', {}) }];
    }
    return [{ json: responder('💜 ¿Qué tipo de taza?\nA. Personalizada\nB. Prediseñada', 'tazas_tipo', {}) }];
  }

  case 'tazas_pred_cantidad': {
    const cantidad = parseCantidad(txt);
    if (cantidad === null) {
      return [{ json: responder('💜 Indícanos una cantidad válida. ¿Cuántas tazas prediseñadas necesitas?', 'tazas_pred_cantidad', {}) }];
    }
    const pedido = { producto: 'taza', tipo: 'predisenada', cantidad };
    return [{ json: cotizar(pedido, 'tazas_pred_cantidad', {}) }];
  }

  case 'tazas_pers_cantidad': {
    const cantidad = parseCantidad(txt);
    if (cantidad === null) {
      return [{ json: responder('💜 Indícanos una cantidad válida. ¿Cuántas tazas personalizadas necesitas?', 'tazas_pers_cantidad', {}) }];
    }
    return [{ json: responder('💜 ¿Todas las tazas llevan el mismo diseño? Responde sí o no.', 'tazas_pers_mismo', { cantidad }) }];
  }

  case 'tazas_pers_mismo': {
    if (txt === 'si' || txt.startsWith('si ') || txt.startsWith('si,')) {
      const pedido = { producto: 'taza', tipo: 'personalizada', cantidad: datosActuales.cantidad, mismoDiseno: true };
      return [{ json: cotizar(pedido, 'tazas_pers_mismo', { cantidad: datosActuales.cantidad }) }];
    }
    if (txt === 'no' || txt.startsWith('no ') || txt.startsWith('no,')) {
      const pedido = { producto: 'taza', tipo: 'personalizada', cantidad: datosActuales.cantidad, mismoDiseno: false };
      return [{ json: cotizar(pedido, 'tazas_pers_mismo', { cantidad: datosActuales.cantidad }) }];
    }
    return [{ json: responder('💜 ¿Todas las tazas llevan el mismo diseño? Responde sí o no.', 'tazas_pers_mismo', datosActuales) }];
  }

  default: {
    return [{ json: responder(MENU, 'menu', {}) }];
  }
}

// Armar respuesta de cotización — Menú Robot Cotizador
// Entrada: $input.first().json con lo del Router + lo del motor (estado, mensaje, ...)
//   estado del motor: 'cotizado' | 'pendiente' | 'no_disponible'
// Salida: { accion, mensaje, nuevoPaso, nuevosDatos, nuevosDatosSql, telefono }
//   - cotizado: se contesta con el mensaje del motor y se vuelve al menú.
//   - pendiente: el motor dice que Karo revisará; se contesta y el chat pasa a Karo.
//   - no_disponible: se contesta con el mensaje del motor y se queda en el mismo
//     paso para que el cliente corrija el dato.

const item = $input.first().json;
const estado = item.estado;

const sqlTexto = (valor) => JSON.stringify(valor).replace(/'/g, "''");

if (estado === 'cotizado') {
  return [{ json: {
    accion: 'responder',
    mensaje: item.mensaje,
    nuevoPaso: 'menu',
    nuevosDatos: {},
    nuevosDatosSql: sqlTexto({}),
    telefono: item.telefono,
  } }];
}

if (estado === 'pendiente') {
  return [{ json: {
    accion: 'karo',
    mensaje: item.mensaje,
    nuevoPaso: 'menu',
    nuevosDatos: {},
    nuevosDatosSql: sqlTexto({}),
    telefono: item.telefono,
  } }];
}

// no_disponible (o cualquier otro estado): se queda en el paso para corregir el dato.
const datosSiFalla = (item.datosSiFalla && typeof item.datosSiFalla === 'object') ? item.datosSiFalla : {};
return [{ json: {
  accion: 'responder',
  mensaje: item.mensaje,
  nuevoPaso: item.pasoSiFalla || 'menu',
  nuevosDatos: datosSiFalla,
  nuevosDatosSql: sqlTexto(datosSiFalla),
  telefono: item.telefono,
} }];
